VRF_ALERT=$(./hlse_core "https://g00gle.com" 2>/dev/null) || true
echo "$VRF_ALERT" | grep -q "Verify independently" \
    && check "p95 verify: present in ALERT band (40-59)" "0" "0" \
    || check "p95 verify: present in ALERT band (40-59)" "0" "1"

