# ─── P53: audit per-finding remediation hints ────────────────────────────

# These assertions inspect the live host's audit verdict, so they need the
# host to actually produce the finding under test: the A7 NOPASSWD check
# only fires on a host whose sudoers still allows passwordless sudo. Probe
# once via --json (audit exits non-zero when findings exist — hence ||true)
# and SKIP on hardened hosts, like the /etc/hosts writability probes do.
P53_AUDIT_JSON=$(./hlse_core --json audit 2>/dev/null || true)
P53_HIGH=$(printf '%s' "$P53_AUDIT_JSON" | python3 -c '
import sys, json
d = json.loads(sys.stdin.readline())
print(sum(1 for f in d["findings"] if f["severity"] >= 4))
' 2>/dev/null || echo 0)
P53_A7_HIGH=$(printf '%s' "$P53_AUDIT_JSON" | python3 -c '
import sys, json
d = json.loads(sys.stdin.readline())
print(sum(1 for f in d["findings"]
          if f["severity"] >= 4 and f["description"].startswith("A7:")))
' 2>/dev/null || echo 0)

# p53: audit HIGH finding shows Fix line
if [ "$P53_A7_HIGH" -gt 0 ]; then
    ./hlse_core audit 2>&1 \
        | grep -q "Fix:.*visudo" \
        && check "p53: audit HIGH finding (A7 NOPASSWD) shows Fix command" "0" "0" \
        || check "p53: audit HIGH finding (A7 NOPASSWD) shows Fix command" "0" "1"
else
    echo "SKIP  p53: no A7 NOPASSWD finding on this host — remediation check skipped"
fi

# p53: audit PASS findings do NOT show Fix line
# Use [PASS] prefix match to avoid matching 'NOPASSWD' in the Fix line
./hlse_core audit 2>&1 \
    | grep "^\s*\[PASS\]" | grep -q "Fix:" \
    && check "p53: audit PASS findings have no Fix line" "0" "1" \
    || check "p53: audit PASS findings have no Fix line" "0" "0"

# p53: audit INFO findings do NOT show Fix line
./hlse_core audit 2>&1 \
    | grep "INFO" | grep -q "Fix:" \
    && check "p53: audit INFO findings have no Fix line" "0" "1" \
    || check "p53: audit INFO findings have no Fix line" "0" "0"

# p53 json: HIGH severity finding carries "fix" field
if [ "$P53_HIGH" -gt 0 ]; then
    ./hlse_core --json audit 2>&1 | python3 -c '
import sys, json
d = json.loads(sys.stdin.readline())
highs = [f for f in d["findings"] if f["severity"] >= 4]
assert len(highs) > 0, "no HIGH findings"
for h in highs:
    assert "fix" in h, f"HIGH finding missing fix field: {h}"
' && check "p53 json: HIGH severity findings carry fix field" "0" "0" \
   || check "p53 json: HIGH severity findings carry fix field" "0" "1"
else
    echo "SKIP  p53 json: no HIGH audit finding on this host — fix-field check skipped"
fi

# p53 json: PASS/INFO findings do NOT carry "fix" field
./hlse_core --json audit 2>&1 | python3 -c '
import sys, json
d = json.loads(sys.stdin.readline())
passes = [f for f in d["findings"] if f["severity"] <= 1]
for p in passes:
    assert "fix" not in p, f"PASS/INFO finding has unexpected fix field: {p}"
' && check "p53 json: PASS/INFO findings have no fix field" "0" "0" \
   || check "p53 json: PASS/INFO findings have no fix field" "0" "1"

# ─── P52: protect/network BLOCK advisory lenses ─────────────────────────

# Create a protect BLOCK test: mass .locked extension mutation
P52_DIR=$(mktemp -d)
for i in $(seq 1 10); do touch "$P52_DIR/doc_${i}.docx.locked"; done

# p52: protect BLOCK shows ransomware pattern
jcheck "p52: protect BLOCK shows ransomware pattern" '"ransomware" in d.get("pattern","").lower()' protect "$P52_DIR"

# R3 stem match (cycle 508): a known note name under a different
# note-carrier extension (.hta/.html/.bmp) fires; .md stays quiet.
R3_DIR=$(mktemp -d)
echo x > "$R3_DIR/how_to_decrypt.hta"
jcheck "protect: ransom-note stem under .hta flags" '"R3: Ransom note" in str(d)' protect "$R3_DIR"
R3B_DIR=$(mktemp -d)
echo x > "$R3B_DIR/readme.md"
jcheck "protect: readme.md stem non-carrier quiet" '"R3: Ransom note" not in str(d)' protect "$R3B_DIR"


# p52: protect BLOCK shows attacker objective (data destruction)
jcheck "p52: protect BLOCK shows data destruction objective" '"data destruction" in d.get("objective","").lower()' protect "$P52_DIR"

# p52: protect BLOCK shows triage (disconnect from network)
jcheck "p52: protect BLOCK shows network disconnect triage" '"disconnect" in d.get("triage","").lower()' protect "$P52_DIR"

