    | grep -q "2 suspicious" \
    && check "pkg: mcp https endpoint stays clean" "0" "0" \
    || check "pkg: mcp https endpoint stays clean" "0" "1"
rm -f "$MCDIR/mcp.json"; printf '{"mcpServers":{"ok":{"command":"npx","args":["-y","pkg"],"url":"https://api.example.com/mcp"}}}' \
    > "$MCDIR/mcp.json"
