WDIR=$(mktemp -d); mkdir -p "$WDIR/.github/workflows"
printf 'on: [pull_request_target]\njobs:\n  t:\n    steps:\n      - uses: actions/checkout@08c6903cd8c0fde910a37f88322edcfb5dd907a8\n        with:\n          ref: ${{ github.head_ref }}\n' \
